// Keys allow React to efficiently diff dynamic list elements
function CustomList({ items }) {
  return (
    <ul>
      {items.map(item => (
        <li key={item.id}>{item.text}</li>
      ))}
    </ul>
  );
}

// Stale Closure Example
function Timer() {
  const [count, setCount] = useState(0);

  useEffect(() => {
    const id = setInterval(() => {
      // BUG: count is always 0 inside this closure!
      // setCount(count + 1);

      // FIX: Use functional state update
      setCount(prev => prev + 1);
    }, 1000);
    return () => clearInterval(id);
  }, []); // Empty dependency array
}

const ExpensiveChild = React.memo(function Child({ onClick }) {
  console.log('Render Child');
  return <button onClick={onClick}>Click me</button>;
});

function Parent() {
